import os
import sys
import django
from django.conf import settings

# Configure Django settings
settings.configure(
    DEBUG=True,
    DATABASES={
        'default': {
            'ENGINE': 'django.db.backends.sqlite3',
            'NAME': ':memory:',
        }
    },
    INSTALLED_APPS=[
        'django.contrib.contenttypes',
        'django.contrib.auth',
    ],
    DEFAULT_AUTO_FIELD='django.db.models.BigAutoField',
)

django.setup()

from django.db import models
from django.db.models import signals

# Test 1: ImageField without width_field/height_field should NOT have post_init signal
class ModelWithoutDimensionFields(models.Model):
    image = models.ImageField(upload_to='images/')

    class Meta:
        app_label = 'test_app'

# Test 2: ImageField with width_field/height_field SHOULD have post_init signal
class ModelWithDimensionFields(models.Model):
    image = models.ImageField(upload_to='images/', width_field='width', height_field='height')
    width = models.IntegerField(null=True)
    height = models.IntegerField(null=True)

    class Meta:
        app_label = 'test_app'

# Check signal connections
def count_post_init_receivers(model_class):
    """Count how many post_init receivers are connected to a model."""
    return len([r for r in signals.post_init.receivers if r[0][1]() is model_class])

print(f"ModelWithoutDimensionFields post_init receivers: {count_post_init_receivers(ModelWithoutDimensionFields)}")
print(f"ModelWithDimensionFields post_init receivers: {count_post_init_receivers(ModelWithDimensionFields)}")

# Expected behavior:
# ModelWithoutDimensionFields should have 0 receivers (no width/height fields)
# ModelWithDimensionFields should have 1 receiver (has width/height fields)

if count_post_init_receivers(ModelWithoutDimensionFields) == 0:
    print("✓ PASS: ModelWithoutDimensionFields correctly has no post_init signal")
else:
    print("✗ FAIL: ModelWithoutDimensionFields should not have post_init signal")

if count_post_init_receivers(ModelWithDimensionFields) == 1:
    print("✓ PASS: ModelWithDimensionFields correctly has post_init signal")
else:
    print("✗ FAIL: ModelWithDimensionFields should have post_init signal")
EOF
